import ast,base64,hashlib,json,re,zlib,zipfile,xml.etree.ElementTree as ET
from pathlib import Path
folder=Path('zips/plugin.video.xship')
base=folder/'plugin.video.xship-2026.10.27.172.zip'
assert hashlib.sha256(base.read_bytes()).hexdigest()=='5fc1030d2e9369322e9de82400e06dc11531e12cddb1db939c1abb3d3ab70aca'
with zipfile.ZipFile(base) as z:
    entries={n:z.read(n) for n in z.namelist() if not n.endswith('/')}
changes=json.loads(zlib.decompress(base64.b64decode('')))
for name,content in changes.items():
    entries[name]=content.encode('utf-8')
for name,content in entries.items():
    if name.endswith('.py'): ast.parse(content,filename=name)
addon=entries['plugin.video.xship/addon.xml'].decode()
assert ET.fromstring(addon).get('version')=='2026.11.12.174'
out=folder/'plugin.video.xship-2026.11.12.174.zip'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
    for name,content in sorted(entries.items()):
        info=zipfile.ZipInfo(name,(2026,11,12,12,0,0));info.compress_type=zipfile.ZIP_DEFLATED;info.external_attr=0o100644<<16
        z.writestr(info,content)
with zipfile.ZipFile(out) as z: assert z.testzip() is None
(folder/'changelog.txt').write_bytes(entries['plugin.video.xship/changelog.txt'])
index=Path('zips/addons.xml'); before=index.read_text()
pattern=r'<addon\b[^>]*\bid="plugin\.video\.xship"[^>]*>.*?</addon>'
replacement=re.sub(r'^<\?xml[^>]*>\s*','',addon)
after,count=re.subn(pattern,lambda m:replacement,before,flags=re.S)
assert count==1
before_others=[ET.tostring(x) for x in ET.fromstring(before) if x.get('id')!='plugin.video.xship']
after_others=[ET.tostring(x) for x in ET.fromstring(after) if x.get('id')!='plugin.video.xship']
assert before_others==after_others
index.write_text(after)
Path('zips/addons.xml.md5').write_text(hashlib.md5(index.read_bytes()).hexdigest())
assert len([x for x in ET.fromstring(after) if x.get('id')=='plugin.video.xship' and x.get('version')=='2026.11.12.174'])==1
print('Release verified:',hashlib.sha256(out.read_bytes()).hexdigest())
